mapper.select:
SELECT id, artifact_id, version_no, infra_file_id, availability_version, sha256, size_bytes,
       declared_media_type, detected_media_type, scan_status_code, scan_provider_code,
       scan_provider_version, availability_status_code, unavailable_reason_code,
       unavailable_at, version_note, created_by, created_at, tenant_id
FROM plt_file_version
WHERE tenant_id = #{query.tenantId}
  AND artifact_id = #{query.artifactId}
  AND version_no = #{query.versionNo}

SELECT id, artifact_id, version_no, infra_file_id, availability_version, sha256, size_bytes,
       declared_media_type, detected_media_type, scan_status_code, scan_provider_code,
       scan_provider_version, availability_status_code, unavailable_reason_code,
       unavailable_at, version_note, created_by, created_at, tenant_id
FROM plt_file_version
WHERE tenant_id = #{query.tenantId}
  AND artifact_id = #{query.artifactId}
  AND version_no = #{query.versionNo}
FOR UPDATE

SELECT id, artifact_id, version_no, infra_file_id, availability_version, sha256, size_bytes,
       declared_media_type, detected_media_type, scan_status_code, scan_provider_code,
       scan_provider_version, availability_status_code, unavailable_reason_code,
       unavailable_at, version_note, created_by, created_at, tenant_id
FROM plt_file_version
WHERE tenant_id = #{query.tenantId}
  AND artifact_id = #{query.artifactId}

  AND (version_no < #{query.afterVersionNo}
       OR (version_no = #{query.afterVersionNo} AND id < #{query.afterId}))

ORDER BY version_no DESC, id DESC
LIMIT #{query.limit}

mapper.update:
UPDATE plt_file_version
SET availability_status_code = #{query.targetStatus},
    unavailable_reason_code = #{query.reasonCode},
    unavailable_at = CASE WHEN #{query.targetStatus} = 'AVAILABLE' THEN NULL ELSE #{query.occurredAt} END,
    availability_version = availability_version + 1
WHERE tenant_id = #{query.tenantId}
  AND artifact_id = #{query.artifactId}
  AND version_no = #{query.versionNo}
  AND availability_version = #{query.expectedAvailabilityVersion}
  AND availability_status_code = #{query.expectedStatus}
